    const Point_2& pj = polygon[j];

    CGAL::Comparison_result y_cmp1 = CGAL::compare_y(pi, point);
    CGAL::Comparison_result y_cmp2 = CGAL::compare_y(pj, point);

    if (y_cmp1 == CGAL::EQUAL && y_cmp2 == CGAL::EQUAL) {
        CGAL::Comparison_result x_cmp1 = CGAL::compare_x(pi, point);
        CGAL::Comparison_result x_cmp2 = CGAL::compare_x(pj, point);
        if ((x_cmp1 == CGAL::EQUAL || x_cmp2 == CGAL::EQUAL) ||
            ((x_cmp1 <= CGAL::EQUAL && x_cmp2 >= CGAL::EQUAL) ||
             (x_cmp1 >= CGAL::EQUAL && x_cmp2 <= CGAL::EQUAL))) {
            return CGAL::ON_BOUNDARY;
        }
        continue;
    }

    if ((y_cmp1 == CGAL::SMALLER && y_cmp2 == CGAL::LARGER) ||
        (y_cmp1 == CGAL::LARGER && y_cmp2 == CGAL::SMALLER)) {
        CGAL::Orientation orient = CGAL::orientation(pj, pi, point);
        if (orient == CGAL::COLLINEAR) {
            return CGAL::ON_BOUNDARY;
        }
        double x_intersect = CGAL::to_double(pj.x()) +
            (CGAL::to_double(pi.x()) - CGAL::to_double(pj.x())) *
            (CGAL::to_double(point.y()) - CGAL::to_double(pj.y())) /
            (CGAL::to_double(pi.y()) - CGAL::to_double(pj.y()));
        CGAL::Comparison_result cmp = CGAL::compare_x(point, Point_2(x_intersect, point.y()));
        if (cmp == CGAL::SMALLER) {
            crossings++;
        } else if (cmp == CGAL::EQUAL) {
            return CGAL::ON_BOUNDARY;
        }
    }
}

return (crossings % 2 == 1) ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;
